-- Mock day-by-day itineraries ("sketches") for a trip's options, shown on hover
-- and in the side-by-side compare. Generated by Claude Haiku and cached here so
-- previews open instantly. Additive; safe to run again.
begin;
create table if not exists public.trip_option_sketches (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  option_id text not null references public.trip_suggestions(id) on delete cascade,
  trip_slug text not null references public.trips(slug),
  hash text not null, -- changes when the option or the trip brief changes
  sketch jsonb not null, -- see OptionSketch in src/lib/sketch.ts
  previous jsonb, -- the version before the last re-sketch, for Undo
  updated_at timestamptz not null default now(),
  primary key (user_id, option_id)
);
alter table public.trip_option_sketches add column if not exists previous jsonb;
-- AI draws per option per day, for the daily spending cap.
alter table public.trip_option_sketches add column if not exists draw_day date;
alter table public.trip_option_sketches add column if not exists draw_count integer not null default 0;
create index if not exists trip_option_sketches_trip on public.trip_option_sketches (user_id, trip_slug);
alter table public.trip_option_sketches enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='trip_option_sketches' and policyname='owner_access') then
    create policy owner_access on public.trip_option_sketches for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
  end if;
  -- Same owner-email wall as 0009.
  if exists (select 1 from pg_proc where proname='portal_is_owner') then
    drop policy if exists owner_only on public.trip_option_sketches;
    create policy owner_only on public.trip_option_sketches as restrictive for all to public
      using (public.portal_is_owner()) with check (public.portal_is_owner());
  end if;
end $$;
revoke all on table public.trip_option_sketches from anon;
commit;
